// Apply the AI decision per event, with a deterministic fallback bucket.
// Keep ALL candidates (including 'keep') so the human can review and override each one.
// AI output items are paired by index with the candidate list.
const aiItems = $input.all();
const candidates = $('Prefilter Candidates (Deterministic)').all();
const out = [];
for (let i = 0; i < candidates.length; i++) {
  const cand = (candidates[i] && candidates[i].json) || {};
  if (!cand.id) continue;
  const a = (aiItems[i] && aiItems[i].json) || {};
  const parsed = a.output || a;
  let action = String(parsed.action || '').trim().toLowerCase();
  const confidence = typeof parsed.confidence === 'number' ? parsed.confidence : 1;
  const destructive = (action === 'cancel' || action === 'decline' || action === 'delete');
  // Fallback bucket: invalid action or low confidence -> keep (no destructive action)
  if (!destructive || confidence < 0.5) action = 'keep';
  out.push({ json: {
    id: cand.id,
    aiAction: action,
    subject: cand.subject,
    day: cand.day,
    start: cand.start,
    isOrganizer: cand.isOrganizer === true,
    aiConfidence: confidence,
    aiReason: String(parsed.reason || '')
  } });
}
return out;

// Build the dynamic per-event review form: one dropdown per candidate event,
// pre-selected with the AI recommendation, overridable to cancel/decline/delete/keep.
const props = $input.all().filter(function (i) { return i.json && i.json.id; });
const rawEvents = $('Get Events In Range').all();
const fmtDay = function (raw) {
  if (!raw) return 'unknown date';
  const d = String(raw).slice(0, 10);
  const parts = d.split('-');
  if (parts.length !== 3) return d;
  return parts[2] + '.' + parts[1] + '.' + parts[0];
};
const fmtTime = function (raw) {
  if (!raw) return '';
  return String(raw).slice(11, 16);
};
// Collect whitelisted (protected) meetings for the description text.
const whitelisted = [];
for (const it of rawEvents) {
  const e = it.json || {};
  if (!e.id) continue;
  if (e.isCancelled === true) continue;
  const categories = Array.isArray(e.categories) ? e.categories : [];
  const isWhitelisted = categories.some(function (c) { return String(c).trim().toLowerCase() === 'whitelist'; });
  if (!isWhitelisted) continue;
  const startRaw = (e.start && e.start.dateTime) ? e.start.dateTime : '';
  whitelisted.push({ day: fmtDay(startRaw), time: fmtTime(startRaw), subject: e.subject || '(no subject)' });
}
// Build one dropdown field per candidate event.
// Role-based options: organizer can only cancel or keep;
// an invitee can decline, delete (own calendar only) or keep.
const fields = [];
for (let i = 0; i < props.length; i++) {
  const e = props[i].json;
  const isOrganizer = e.isOrganizer === true;
  const options = isOrganizer
    ? [{ option: 'cancel' }, { option: 'keep' }]
    : [{ option: 'decline' }, { option: 'delete' }, { option: 'keep' }];
  const allowed = options.map(function (o) { return o.option; });
  // Make sure the pre-selected value is actually offered for this role.
  const defaultValue = allowed.indexOf(e.aiAction) !== -1 ? e.aiAction : 'keep';
  const conf = Math.round((typeof e.aiConfidence === 'number' ? e.aiConfidence : 1) * 100);
  let reason = String(e.aiReason || '');
  if (reason.length > 140) reason = reason.slice(0, 137) + '...';
  const role = isOrganizer ? 'organizer' : 'invited';
  let label = e.day + ' — ' + e.subject + '  [' + role + ']  ▸ AI: ' + defaultValue + ' (' + conf + '%)';
  if (reason) label += ' — ' + reason;
  fields.push({ fieldLabel: label, fieldName: 'decision_' + i, fieldType: 'dropdown', fieldOptions: { values: options }, defaultValue: defaultValue, requiredField: true });
}
// Description: intro + whitelist list (HTML).
let desc = '<p>The AI proposed an action for each meeting below. Review each one and change it if needed, then confirm.</p>';
desc += '<p><b>' + whitelisted.length + '</b> whitelisted meeting(s) are protected and will NOT be changed';
if (whitelisted.length > 0) {
  desc += ':</p><div style="list-style:none;padding:0;margin:0;">';
  for (const w of whitelisted) { desc += '<div>' + w.day + ' — ' + w.subject + '</div>'; }
  desc += '</div>';
} else {
  desc += '.</p>';
}
// 'No events' completion text (same layout as before).
let noEventsText = '';
if (whitelisted.length === 0) {
  noEventsText = 'No events were determined in the selected time frame.';
} else {
  noEventsText = whitelisted.length + ' determined meeting(s):\n\n';
  const lines = [];
  for (const w of whitelisted) { const when = w.time ? (w.day + ' ' + w.time) : w.day; lines.push(when + ' — ' + w.subject); }
  noEventsText += lines.join('\n');
}
noEventsText += '\n\nYou can close this window.';
return [{ json: { formFieldsJson: JSON.stringify(fields), reviewDescriptionHtml: desc, noEventsText: noEventsText, count: props.length, whitelistedCount: whitelisted.length } }];

// One log row per candidate event: AI decision vs. human final decision.
const cands = $('Classify Proposals').all().filter(function (i) { return i.json && i.json.id; });
const form = $('Review & Approve').first().json || {};
const runId = String($execution.id);
const now = new Date().toISOString();
const out = [];
for (let i = 0; i < cands.length; i++) {
  const e = cands[i].json;
  let human = String(form['decision_' + i] || e.aiAction).trim().toLowerCase();
  const overridden = human !== e.aiAction;
  out.push({ json: {
    run_id: runId,
    logged_at: now,
    event_subject: e.subject,
    event_day: e.day,
    ai_action: e.aiAction,
    ai_confidence: (typeof e.aiConfidence === 'number' ? e.aiConfidence : 1),
    ai_reason: e.aiReason,
    human_final_action: human,
    was_overridden: overridden
  } });
}
return out;

// Emit one item per event the human wants to act on (cancel/decline/delete).
// 'keep' events are skipped. If nothing is left to execute, emit a sentinel.
const cands = $('Classify Proposals').all().filter(function (i) { return i.json && i.json.id; });
const form = $('Review & Approve').first().json || {};
const out = [];
for (let i = 0; i < cands.length; i++) {
  const e = cands[i].json;
  const action = String(form['decision_' + i] || e.aiAction).trim().toLowerCase();
  if (action === 'cancel' || action === 'decline' || action === 'delete') {
    out.push({ json: { id: e.id, action: action, subject: e.subject, hasExec: true } });
  }
}
if (out.length === 0) return [{ json: { hasExec: false } }];
return out;
